let lang=localStorage.getItem("masaha-language")||"ar",me=null,authMode="login",reportTarget=null,toastTimer,backendOnline=true,knownReportIds=null,lastUnread=null,categories=[];
const $=s=>document.querySelector(s), t=k=>T[lang][k]||k, esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function formatBody(value){return esc(value).replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>").replace(/\n/g,"<br>")}
function applyTheme(){const theme=localStorage.getItem("masaha-theme")||"light";document.documentElement.dataset.theme=theme}
const localKey="masaha-local-topics",draftKey="masaha-topic-draft";let messagePeer=null,messageRefreshTimer=null,installPrompt=null;
function badgeLabel(key){return t(`badge${key.split("_").map(x=>x[0].toUpperCase()+x.slice(1)).join("")}`)}
function categoryName(slug){const c=categories.find(x=>x.slug===slug);return c?(lang==="ar"?c.name_ar:c.name_en):t(slug)}
function categoryOptions(selected=""){return categories.map(c=>`<option value="${esc(c.slug)}" ${c.slug===selected?"selected":""}>${esc(categoryName(c.slug))}</option>`).join("")}
async function loadCategories(){const fallback=[{slug:"programming",name_ar:"البرمجة",name_en:"Programming",description:"أسئلة وتجارب ومشاريع برمجية.",topic_count:0},{slug:"learning",name_ar:"التعلّم",name_en:"Learning",description:"مصادر وتجارب تساعدنا على التعلّم.",topic_count:0},{slug:"general",name_ar:"نقاش عام",name_en:"General",description:"موضوعات وأفكار عامة.",topic_count:0}];try{categories=(await api("/api/categories")).categories}catch{categories=fallback}renderCategories()}
function renderCategories(){const list=$("#categories-list"),filter=$("#category-filter"),keep=filter?.value||"";if(list)list.innerHTML=categories.map(c=>`<div class="category category-card"><a href="#category/${encodeURIComponent(c.slug)}"><span><b>${esc(categoryName(c.slug))}</b><small>${esc(c.description||"")}</small></span><span class="tag">${Number(c.topic_count)||0}</span></a>${me?`<button type="button" class="follow-category" data-follow-category="${esc(c.slug)}">${c.followed_by_me?t("unfollow"):t("follow")}</button>`:""}</div>`).join("");if(filter)filter.innerHTML=`<option value="">${t("allCategories")}</option>${categoryOptions(keep)}`;for(const id of ["topic-form","edit-topic-form"]){const select=document.querySelector(`#${id} select[name=category]`);if(select){const value=select.value;select.innerHTML=categoryOptions(value)}}renderAdminCategories()}
function renderAdminCategories(){const el=$("#admin-categories");if(!el)return;el.innerHTML=categories.map(c=>`<div class="category-admin-row"><span><b>${esc(categoryName(c.slug))}</b><small>${esc(c.slug)} · ${Number(c.topic_count)||0}</small></span>${!["programming","learning","general"].includes(c.slug)?`<button type="button" class="small-button" data-delete-category="${esc(c.slug)}">${t("deleteCategory")}</button>`:""}</div>`).join("")}

function localTopics(){try{return JSON.parse(localStorage.getItem(localKey)||"[]")}catch{return[]}}
function saveLocalTopics(xs){localStorage.setItem(localKey,JSON.stringify(xs))}
function localApi(path,opts={}){const method=(opts.method||"GET").toUpperCase(),body=typeof opts.body==="string"?JSON.parse(opts.body||"{}"):{};let xs=localTopics();if(path==="/api/me")return{user:null};if(path==="/api/categories")return{categories:[{slug:"programming",name_ar:"البرمجة",name_en:"Programming",description:"",topic_count:0},{slug:"learning",name_ar:"التعلّم",name_en:"Learning",description:"",topic_count:0},{slug:"general",name_ar:"نقاش عام",name_en:"General",description:"",topic_count:0}]};if(path.startsWith("/api/topics?")||path==="/api/topics"){if(method==="GET"){const u=new URL(path,"http://local"),q=(u.searchParams.get("q")||"").toLowerCase(),cat=u.searchParams.get("category")||"",sort=u.searchParams.get("sort")||"newest";let items=xs.filter(x=>(!cat||x.category===cat)&&(!q||(x.title+" "+x.body).toLowerCase().includes(q)));items.sort(sort==="popular"?(a,b)=>(b.likeCount||0)-(a.likeCount||0)||b.createdAt-a.createdAt:sort==="oldest"?(a,b)=>a.createdAt-b.createdAt:(a,b)=>b.createdAt-a.createdAt);const total=items.length,limit=Number(u.searchParams.get("limit")||20),offset=Number(u.searchParams.get("offset")||0);return{topics:items.slice(offset,offset+limit),total}}if(method==="POST"){const x={id:"local-"+Date.now(),title:body.title,body:body.body,category:body.category,tags:String(body.tags||"").split(",").map(a=>a.trim().replace(/^#/,"")).filter(Boolean).slice(0,8),createdAt:Date.now()/1000,user:{id:"local",username:"guest",displayName:lang==="ar"?"زائر":"Guest",avatarUrl:""},commentCount:0,likeCount:0,imageUrl:body.image||"",likedByMe:false,bookmarkedByMe:false,comments:[]};xs.unshift(x);saveLocalTopics(xs);return{id:x.id}}}const m=path.match(/^\/api\/topics\/([^/?]+)(?:\/(comments|like|bookmark))?/);if(m){const x=xs.find(a=>a.id===m[1]);if(!x)throw Error(t("failed"));if(!m[2])return{topic:x,comments:x.comments||[]};if(m[2]==="comments"&&method==="POST"){x.comments=x.comments||[];x.comments.push({id:"local-comment-"+Date.now(),body:body.body,createdAt:Date.now()/1000,user:x.user});x.commentCount=x.comments.length;saveLocalTopics(xs);return{ok:true}}if(m[2]==="like"){x.likedByMe=!x.likedByMe;x.likeCount=Math.max(0,x.likeCount+(x.likedByMe?1:-1));saveLocalTopics(xs);return{ok:true}}if(m[2]==="bookmark"){x.bookmarkedByMe=!x.bookmarkedByMe;saveLocalTopics(xs);return{saved:x.bookmarkedByMe}}}if(path==="/api/bookmarks")return{topics:xs.filter(x=>x.bookmarkedByMe)};if(path.startsWith("/api/notifications"))return{notifications:[],unread:0};throw Error(lang==="ar"?"هذه الميزة تحتاج تشغيل خادم Python.":"This feature requires the Python server.")}
async function api(path,opts={}){if(!backendOnline)return localApi(path,opts);const headers={...(opts.headers||{})};if(!(opts.body instanceof FormData))headers["Content-Type"]="application/json";try{const r=await fetch(path,{...opts,headers,credentials:"same-origin"});let d,validJson=true;try{d=await r.json()}catch{validJson=false}if(!validJson){backendOnline=false;return localApi(path,opts)}if(!r.ok)throw Error(d.error||t("failed"));return d}catch(e){if(e instanceof TypeError||e instanceof SyntaxError){backendOnline=false;return localApi(path,opts)}throw e}}
function toast(s){const e=$("#toast");e.textContent=s;e.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove("show"),3200)}
function date(s){return new Intl.DateTimeFormat(lang==="ar"?"ar":"en",{dateStyle:"medium",timeStyle:"short"}).format(new Date(s*1000))}
function setLang(){document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.querySelectorAll("[data-t]").forEach(e=>e.textContent=t(e.dataset.t));document.querySelectorAll("[data-t-placeholder]").forEach(e=>e.placeholder=t(e.dataset.tPlaceholder));$("#language").textContent=lang==="ar"?"English":"العربية";$("#profile-link").hidden=!me;$("#settings-open").hidden=!me;$("#notifications-open").hidden=!me;$("#messages-open").hidden=!me;$("#following-link").hidden=!me;$("#notifications-open").setAttribute("aria-label",t("notifications"));$("#bookmarks-link").hidden=!me;$("#reports-link").hidden=!(me&&me.role==="admin");$("#login-open").textContent=me?`${me.displayName} · ${t("logout")}`:t("login");$("#theme-toggle").textContent=document.documentElement.dataset.theme==="dark"?"☀️":"🌙";renderCategories()}
function avatar(user){return user.avatarUrl?`<img class="avatar-img" src="${esc(user.avatarUrl)}" alt="">`:`<span>${esc((user.displayName||"?").slice(0,1))}</span>`}
function card(x){return `<article class="topic ${x.isPinned?"topic-pinned":""}"><div class="avatar">${avatar(x.user)}</div><div class="topic-body">${x.isPinned?`<span class="pin-label">📌 ${t("pinned")}</span>`:""}<a class="topic-title" href="#topic/${x.id}">${esc(x.title)}</a><p>${formatBody(x.body.length>300?x.body.slice(0,300)+"…":x.body)}</p>${x.hasPoll?`<span class="poll-badge">▤ ${t("votes")}</span>`:""}${x.imageUrl?`<img class="topic-image" src="${esc(x.imageUrl)}" alt="">`:""}${x.tags?.length?`<div class="topic-tags">${x.tags.map(tag=>`<a href="#tag/${encodeURIComponent(tag)}" class="tag-chip">#${esc(tag)}</a>`).join("")}</div>`:""}<div class="meta"><span class="tag">${esc(categoryName(x.category))}</span><a class="profile-link" href="#profile/${x.user.id}">${t("by")} ${esc(x.user.displayName)}</a><span>${date(x.createdAt)}</span><span>💬 ${x.commentCount}</span><span>♥ ${x.likeCount}</span></div><div class="topic-actions"><button class="small-button" data-like="${x.id}">${x.likedByMe?t("unlike"):t("like")} · ${x.likeCount}</button><button class="small-button" data-bookmark="${x.id}">${x.bookmarkedByMe?t("unbookmark"):t("bookmark")}</button><button class="small-button" data-report-type="topic" data-report-id="${x.id}">${t("report")}</button>${me&&me.role==="admin"?`<button class="small-button" data-pin-topic="${x.id}">${x.isPinned?t("unpin"):t("pin")}</button>`:""}${me&&(me.role==="admin"||Number(me.id)===Number(x.user.id))?`<button class="small-button" data-edit-topic="${x.id}">${t("edit")}</button><button class="small-button" data-admin="delete" data-type="topic" data-id="${x.id}">${t("remove")}</button>`:""}</div></div></article>`}
let topicPage=0;const topicPageSize=20;
async function loadTopics(q="",cat="",sort=$("#sort-filter").value,append=false){const c=$("#content"),more=$("#load-more");if(!append){topicPage=0;c.innerHTML=`<div class="empty">${t("loading")}</div>`}try{const p=new URLSearchParams();if(q)p.set("q",q);if(cat)p.set("category",cat);if(sort)p.set("sort",sort);p.set("limit",topicPageSize);p.set("offset",topicPage*topicPageSize);const d=await api(`/api/topics?${p}`);const html=d.topics.map(card).join("");if(append)c.insertAdjacentHTML("beforeend",html);else c.innerHTML=html||`<div class="empty">${t("noTopics")}</div>`;more.hidden=(topicPage+1)*topicPageSize>=d.total;if(d.topics.length)more.hidden=(topicPage+1)*topicPageSize>=d.total}catch(e){if(append){topicPage=Math.max(0,topicPage-1);toast(e.message)}else c.innerHTML=`<div class="empty">${esc(e.message)}</div>`;more.hidden=true}}

async function openTopic(id){$("#load-more").hidden=true;const c=$("#content");c.innerHTML=`<div class="empty">${t("loading")}</div>`;try{const d=await api(`/api/topics/${id}`),x=d.topic;$("#view-title").textContent=x.title;document.title=`${x.title} | ${t("brand")}`;c.innerHTML=`<article class="topic"><div class="avatar">${avatar(x.user)}</div><div class="topic-body"><div class="meta">${x.isPinned?`<span class="pin-label">📌 ${t("pinned")}</span>`:""}<span class="tag">${esc(categoryName(x.category))}</span><a class="profile-link" href="#profile/${x.user.id}">${esc(x.user.displayName)}</a><span>${date(x.createdAt)}</span></div><p class="detail-body">${formatBody(x.body)}</p>${x.imageUrl?`<img class="topic-image" src="${esc(x.imageUrl)}" alt="">`:""}${x.tags?.length?`<div class="topic-tags">${x.tags.map(tag=>`<a href="#tag/${encodeURIComponent(tag)}" class="tag-chip">#${esc(tag)}</a>`).join("")}</div>`:""}${pollMarkup(d.poll,x.id)}<div class="topic-actions"><button class="small-button" data-like="${x.id}">${x.likedByMe?t("unlike"):t("like")} · ${x.likeCount}</button><button class="small-button" data-bookmark="${x.id}">${x.bookmarkedByMe?t("unbookmark"):t("bookmark")}</button><button class="small-button" data-report-type="topic" data-report-id="${x.id}">${t("report")}</button>${me&&me.role==="admin"?`<button class="small-button" data-pin-topic="${x.id}">${x.isPinned?t("unpin"):t("pin")}</button>`:""}</div></div></article><section class="comments"><h3>${d.comments.length} ${t("replies")}</h3>${d.comments.length?d.comments.map(a=>`<article class="comment ${Number(x.bestAnswerId)===Number(a.id)?"best-answer":""}"><div class="meta">${Number(x.bestAnswerId)===Number(a.id)?`<span class="tag best-answer-label">✓ ${t("bestAnswer")}</span>`:""}<a class="profile-link" href="#profile/${a.user.id}">${esc(a.user.displayName)}</a><span>${date(a.createdAt)}</span></div><p>${esc(a.body)}</p><div class="topic-actions"><button class="small-button" data-report-type="comment" data-report-id="${a.id}">${t("report")}</button>${me&&(Number(me.id)===Number(x.user.id)||me.role==="admin")?`<button class="small-button" data-best-answer="${x.id}" data-comment-id="${a.id}">${Number(x.bestAnswerId)===Number(a.id)?t("bestAnswer"):t("markBestAnswer")}</button>`:""}${me&&(me.role==="admin"||Number(me.id)===Number(a.user.id))?`<button class="small-button" data-edit-comment="${a.id}" data-body="${esc(a.body)}">${t("editReply")}</button><button class="small-button" data-admin="delete" data-type="comment" data-id="${a.id}">${t("deleteReply")}</button>`:""}</div></article>`).join(""):`<p class="muted">${t("noComments")}</p>`}${me||!backendOnline?`<form class="comment-form" id="comment-form"><textarea name="body" maxlength="3000" required placeholder="${t("writeReply")}"></textarea><button class="cta">${t("sendReply")}</button></form>`:`<button class="cta" data-auth="login">${t("login")}</button>`}</section>`;const f=$("#comment-form");if(f)f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/topics/${id}/comments`,{method:"POST",body:JSON.stringify({body:new FormData(f).get("body")})});toast(t("sent"));openTopic(id)}catch(err){toast(err.message)}}}catch(e){c.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function openProfile(id){$("#load-more").hidden=true;const c=$("#content");try{const d=await api(`/api/users/${id}`),u=d.user;$("#view-title").textContent=t("profile");c.innerHTML=`<section class="profile-box">${u.coverUrl?`<img class="profile-cover" src="${esc(u.coverUrl)}" alt="">`:""}<div class="avatar profile-avatar">${avatar(u)}</div><h2>${esc(u.displayName)}</h2><div class="muted">@${esc(u.username)} · ${t("memberSince")} ${date(u.createdAt)}</div><p>${esc(u.bio||t("profileHint"))}</p><div class="profile-stats"><span><b>${u.topicCount||0}</b> ${t("topicCount")}</span><span><b>${u.replyCount||0}</b> ${t("replyCount")}</span><span><b>${u.points||0}</b> ${t("points")}</span><span><b>${u.followerCount||0}</b> ${t("followers")}</span></div>${u.badges?.length?`<div class="member-badges">${u.badges.map(b=>`<span class="badge-chip">🏅 ${esc(badgeLabel(b))}</span>`).join("")}</div>`:""}${me&&Number(me.id)!==Number(u.id)?`<button class="cta" data-message-user="${u.id}" data-message-name="${esc(u.displayName)}">✉ ${t("messageTo")}</button><button class="cta follow-member" data-follow-user="${u.id}">${u.followedByMe?t("unfollow"):t("follow")}</button>`:""}${me&&me.id===u.id?`<form id="cover-form"><label class="text-button">${t("editCover")}<input type="file" name="cover" accept="image/png,image/jpeg,image/webp" hidden></label></form><form id="avatar-form"><label class="text-button">${t("uploadAvatar")}<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp" hidden></label></form><button class="cta" id="edit-profile">${t("editProfile")}</button><button class="small-button" id="profile-settings">${t("settings")}</button><form id="profile-form" class="comment-form" hidden><input name="displayName" minlength="2" maxlength="50" value="${esc(u.displayName)}" required><textarea name="bio" maxlength="500">${esc(u.bio)}</textarea><button class="cta">${t("save")}</button></form>`:""}</section><h3>${t("posts")}</h3>${d.topics.length?d.topics.map(card).join(""):`<p class="muted">${t("noTopics")}</p>`}<h3>${t("replyCount")}</h3>${d.replies?.length?d.replies.map(r=>`<a class="profile-reply" href="#topic/${r.topic_id}"><b>${esc(r.title)}</b><span>${esc(r.body.slice(0,150))}</span><small>${date(r.created_at)}</small></a>`).join(""):`<p class="muted">${t("noComments")}</p>`}`;const ps=$("#profile-settings");if(ps)ps.onclick=()=>openSettings();const ed=$("#edit-profile");if(ed)ed.onclick=()=>{$("#profile-form").hidden=false;ed.hidden=true};const f=$("#profile-form");if(f)f.onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/me/profile",{method:"PUT",body:JSON.stringify(Object.fromEntries(new FormData(f)))});me={...me,...d.user};toast(t("profileSaved"));openProfile(id)}catch(err){toast(err.message)}};const cf=$("#cover-form input");if(cf)cf.onchange=async()=>{if(cf.files[0])try{const image=await fileData(cf.files[0]);await api("/api/me/cover",{method:"POST",body:JSON.stringify({image})});openProfile(id)}catch(err){toast(err.message)}};const af=$("#avatar-form input");if(af)af.onchange=async()=>{if(af.files[0])try{const image=await fileData(af.files[0]);const d=await api("/api/me/avatar",{method:"POST",body:JSON.stringify({image})});me.avatarUrl=d.avatarUrl;openProfile(id)}catch(err){toast(err.message)}}}catch(e){c.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadBookmarks(){$("#load-more").hidden=true;const p=new URLSearchParams({sort:$("#sort-filter").value||"newest"});if($("#search").value)p.set("q",$("#search").value);if($("#category-filter").value)p.set("category",$("#category-filter").value);const d=await api(`/api/bookmarks?${p}`);$("#view-title").textContent=t("bookmarks");$("#content").innerHTML=d.topics.length?d.topics.map(card).join(""):`<div class="empty">${t("noTopics")}</div>`}
async function loadFollowing(){$("#load-more").hidden=true;$("#view-title").textContent=t("followingFeed");try{const d=await api("/api/following-feed");$("#content").innerHTML=d.topics.length?d.topics.map(card).join(""):`<div class="empty">${t("emptyFollowing")}</div>`}catch(e){$("#content").innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function pollMarkup(poll,topicId){if(!poll)return "";const choices=poll.options.map((option,index)=>{const count=poll.counts[index]||0,percent=poll.total?Math.round(count*100/poll.total):0;return poll.selected===null?`<button class="poll-option" data-vote="${topicId}" data-option="${index}">${esc(option)}</button>`:`<div class="poll-result"><div><span>${esc(option)}</span><b>${percent}% · ${count}</b></div><i style="width:${percent}%"></i></div>`}).join("");return `<section class="poll-box"><h3>${esc(poll.question)}</h3>${choices}<p class="muted">${poll.total} ${t("votes")}</p></section>`}
async function route(){const h=decodeURIComponent(location.hash||"#home"),query=new URLSearchParams(location.search);$("#help-section").hidden=true;if(h==="#help"){$("#forum-content").hidden=true;$("#reports-section").hidden=true;$("#help-section").hidden=false;document.title=`${t("help")} | ${t("brand")}`;return}if(h==="#reports"&&me&&me.role==="admin"){$("#forum-content").hidden=true;$("#help-section").hidden=true;$("#reports-section").hidden=false;document.title=`${t("reports")} | ${t("brand")}`;return drawAdmin()}$("#forum-content").hidden=false;$("#reports-section").hidden=true;if(query.get("topic"))return openTopic(query.get("topic"));if(h.startsWith("#topic/"))return openTopic(h.split("/")[1]);if(h.startsWith("#profile/"))return openProfile(h.split("/")[1]);if(h==="#bookmarks"&&me)return loadBookmarks();if(h==="#following"&&me)return loadFollowing();if(h.startsWith("#tag/")){return loadTopics(h.slice(5),"")}if(h.startsWith("#category/")){const cat=h.split("/")[1];$("#category-filter").value=cat;return loadTopics($("#search").value,cat)}$("#view-title").textContent=t("latest");document.title=`${t("brand")} | ${t("latest")}`;$("#category-filter").value="";return loadTopics($("#search").value,"")}
function fileData(file){return new Promise((resolve,reject)=>{if(file.size>2_000_000)return reject(Error("Image must be under 2 MB"));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function auth(mode="login"){authMode=mode;$("#auth-dialog").showModal();authTabs()}
function authTabs(){const reg=authMode==="register";$("#register-tab").classList.toggle("active",reg);$("#login-tab").classList.toggle("active",!reg);$("#name-field").hidden=!reg;$("#auth-name").required=reg;$("#username-field").hidden=!reg;$("#auth-username").required=reg;$("#auth-username").disabled=!reg;$("#auth-title").textContent=t(reg?"register":"login");$("#auth-submit").textContent=t(reg?"register":"login");$("#auth-error").textContent=""}
function handleAccountLinks(){const p=new URLSearchParams(location.search);if(p.has("reset")){window.resetToken=p.get("reset");$("#reset-dialog").showModal()}}
function openVerification(email){$("#verify-email").value=email||"";$("#verification-error").textContent="";$("#verify-dialog").showModal()}
$("#verification-form").onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{await api("/api/verify",{method:"POST",body:JSON.stringify(data)});$("#verify-dialog").close();toast(t("verifyDone"));auth("login");$("#auth-form input[name=email]").value=data.email}catch(err){$("#verification-error").textContent=err.message==="CODE_INVALID"||err.message==="CODE_EXPIRED"?t("codeInvalid"):err.message}};
$("#resend-code").onclick=async()=>{try{await api("/api/verification-resend",{method:"POST",body:JSON.stringify({email:$("#verify-email").value})});toast(t("verifySent"))}catch(err){toast(err.message==="RESEND_COOLDOWN"?t("resendCooldown"):err.message)}}
function drawAdmin(){if(!me||me.role!=="admin")return;$("#admin-panel").hidden=false;api("/api/admin/moderation-log").then(d=>{$("#moderation-log").innerHTML=d.entries.length?d.entries.map(x=>`<div class="member-row"><span><b>${esc(x.admin_name)}</b> · ${t(`action_${x.action}`)} · ${esc(x.target_type)} #${x.target_id}</span><small>${date(x.created_at)}</small></div>`).join(""):`<p class="muted">—</p>`}).catch(()=>{});api(`/api/admin/reports?status=${$("#report-status")?.value||"open"}`).then(d=>{const ids=d.reports.map(r=>r.id);if((!$("#report-status")||$("#report-status").value==="open")&&knownReportIds!==null){const added=ids.filter(id=>!knownReportIds.includes(id));if(added.length)toast(lang==="ar"?`وصل ${added.length} بلاغ جديد`:`${added.length} new report${added.length===1?"":"s"}`)}if(!$("#report-status")||$("#report-status").value==="open")knownReportIds=ids;const reportQuery=$("#report-search")?.value.trim().toLowerCase()||"";const visible=d.reports.filter(r=>(!$("#report-type")?.value||r.target_type===$("#report-type").value)&&(!reportQuery||`${r.reason} ${r.reporter_name||r.reporter} ${r.topic_title||""} ${r.target_id}`.toLowerCase().includes(reportQuery)));$("#reports-list").innerHTML=visible.length?visible.map(r=>`<div class="report-item"><b>${esc(r.target_type==="topic"?t("topicsOnly"):t("repliesOnly"))} #${r.target_id}</b><p><a href="#topic/${r.target_topic_id}">${esc(r.topic_title||"")}</a></p><p>${esc(r.reason)}</p><small>${t("reportedBy")}: ${esc(r.reporter_name||r.reporter)} · ${date(r.created_at)}</small><div class="topic-actions">${r.status==="open"?`<button class="small-button" data-admin="resolve" data-id="${r.id}">${t("resolve")}</button>`:`<span class="tag">${t("closedReports")}</span>`}<button class="small-button" data-admin="delete" data-type="${r.target_type}" data-id="${r.target_id}">${t("remove")}</button></div></div>`).join(""):`<p class="muted">${t($("#report-status")?.value==="resolved"?"noClosedReports":"noReports")}</p>`}).catch(()=>{});renderAdminCategories();api("/api/admin/stats").then(d=>{$("#admin-stats").innerHTML=[["statsMembers",d.stats.members],["statsTopics",d.stats.topics],["statsReplies",d.stats.replies],["statsReports",d.stats.openReports],["statsToday",d.stats.todayTopics]].map(([k,v])=>`<div class="stat-tile"><b>${v}</b><span>${t(k)}</span></div>`).join("")}).catch(()=>{});api("/api/admin/users").then(d=>{$("#members-list").innerHTML=d.users.map(u=>`<div class="member-row"><span>${esc(u.display_name)} (@${esc(u.username)}) ${u.is_banned?`· ${t("banned")}`:""}</span>${u.role!=="admin"?`<button class="small-button" data-ban="${u.id}">${u.is_banned?t("unban"):t("ban")}</button>`:""}</div>`).join("")||`<p class="muted">${t("noMembers")}</p>`}).catch(()=>{})}
async function notifications(){if(!me)return auth("login");const d=await api("/api/notifications?mark=1");$("#notification-count").hidden=true;$("#notifications-list").innerHTML=d.notifications.length?d.notifications.map(n=>{const key=n.kind==="like"?"likeNotice":n.kind==="followed_topic"?"followedNotice":n.kind==="reply_comment"?"replyCommentNotice":"replyNotice";return `<a class="notification-row ${n.seen?"":"notification-unread"}" href="#topic/${n.topic_id}"><b>${esc(n.actor)}</b> ${t(key)}<br><span>${esc(n.title)} · ${date(n.created_at)}</span></a>`}).join(""):`<p class="muted">${t("noNotifications")}</p>`;$("#notifications-dialog").showModal()}
$("#language").onclick=()=>{lang=lang==="ar"?"en":"ar";localStorage.setItem("masaha-language",lang);setLang();renderCategories();route()};$("#search-form").onsubmit=e=>{e.preventDefault();if(location.hash==="#bookmarks")loadBookmarks();else{location.hash="#home";loadTopics($("#search").value,$("#category-filter").value)}};$("#category-filter").onchange=()=>location.hash==="#bookmarks"?loadBookmarks():loadTopics($("#search").value,$("#category-filter").value);$("#sort-filter").onchange=()=>location.hash==="#bookmarks"?loadBookmarks():loadTopics($("#search").value,$("#category-filter").value);
$("#login-open").onclick=async()=>{if(me){await api("/api/logout",{method:"POST",body:"{}"});me=null;lastUnread=null;setLang();location.hash="#home"}else if(!backendOnline)toast(lang==="ar"?"تسجيل الحسابات يحتاج تشغيل خادم Python.":"Accounts require the Python server.");else auth("login")};$("#join-button").onclick=()=>backendOnline?auth("register"):toast(lang==="ar"?"تسجيل الحسابات يحتاج تشغيل خادم Python.":"Accounts require the Python server.");$("#login-tab").onclick=()=>{authMode="login";authTabs()};$("#register-tab").onclick=()=>{authMode="register";authTabs()};$("#profile-link").onclick=()=>me&&(location.hash=`#profile/${me.id}`);$("#settings-open").onclick=()=>openSettings();function openSettings(){if(!me)return;$("#settings-form").elements.email.value=me.email||"";$("#settings-form").elements.currentPassword.value="";$("#settings-form").elements.newPassword.value="";$("#settings-error").textContent="";$("#settings-dialog").showModal()}$("#settings-form").onsubmit=async e=>{e.preventDefault();try{const result=await api("/api/me/settings",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$("#settings-dialog").close();toast(t("settingsSaved"));if(result.verificationRequired){const changedEmail=result.user.email;me=null;lastUnread=null;setLang();openVerification(changedEmail)}else{me=result.user;setLang()}}catch(err){$("#settings-error").textContent=err.message==="CURRENT_PASSWORD_INVALID"?t("currentPasswordInvalid"):err.message}};$("#bookmarks-link").onclick=()=>{if(me)location.hash="#bookmarks";else auth("login")};$("#following-link").onclick=()=>{if(me)location.hash="#following";else auth("login")};$("#theme-toggle").onclick=()=>{const next=document.documentElement.dataset.theme==="dark"?"light":"dark";localStorage.setItem("masaha-theme",next);applyTheme();setLang()};$("#notifications-open").onclick=()=>notifications().catch(e=>toast(e.message));$("#messages-open").onclick=()=>openInbox().catch(e=>toast(e.message));async function openInbox(){messagePeer=null;$("#messages-title").textContent=t("messages");$("#messages-list").hidden=true;$("#message-form").hidden=true;$("#conversations-list").hidden=false;$("#messages-dialog").showModal();const d=await api("/api/inbox");$("#conversations-list").innerHTML=d.conversations.length?d.conversations.map(c=>`<button class="conversation-row" data-open-conversation="${c.id}" data-conversation-name="${esc(c.display_name)}"><b>${esc(c.display_name)}</b><span>${esc((c.last_body||"").slice(0,100))}</span>${c.unread?`<i>${c.unread}</i>`:""}</button>`).join(""):`<p class="muted">${t("noMessages")}</p>`;}$("#conversations-list").addEventListener("click",e=>{const c=e.target.closest("[data-open-conversation]");if(c){messagePeer={id:Number(c.dataset.openConversation),name:c.dataset.conversationName};openMessages()}});async function openMessages(){if(!messagePeer)return;$("#messages-title").textContent=`${t("messages")}: ${messagePeer.name}`;$("#conversations-list").hidden=true;$("#messages-list").hidden=false;$("#message-form").hidden=false;$("#messages-dialog").showModal();await refreshMessages();clearInterval(messageRefreshTimer);messageRefreshTimer=setInterval(refreshMessages,4000)}async function refreshMessages(){if(!messagePeer||!$("#messages-dialog").open)return;try{const d=await api(`/api/messages/${messagePeer.id}`);$("#messages-list").innerHTML=d.messages.map(m=>`<div class="direct-message ${Number(m.sender_id)===Number(me.id)?"mine":""}"><p>${esc(m.body)}</p><small>${date(m.created_at)}</small></div>`).join("")||`<p class="muted">${t("noMessages")}</p>`;$("#messages-list").scrollTop=$("#messages-list").scrollHeight}catch(e){toast(e.message)}}$("#messages-dialog").addEventListener("close",()=>clearInterval(messageRefreshTimer));$("#message-form").onsubmit=async e=>{e.preventDefault();if(!messagePeer)return;const f=e.currentTarget,body=f.elements.body.value.trim();try{await api("/api/messages",{method:"POST",body:JSON.stringify({recipientId:messagePeer.id,body})});f.reset();await refreshMessages()}catch(err){toast(err.message)}};
$("#auth-form").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const result=await api(`/api/${authMode}`,{method:"POST",body:JSON.stringify(d)});if(result.verificationRequired){$("#auth-dialog").close();openVerification(d.email);toast(t("verifySent"));return}me=result.user;lastUnread=null;$("#auth-dialog").close();setLang();await loadCategories();drawAdmin();toast(t("sent"));route()}catch(err){$("#auth-error").textContent=err.message==="USERNAME_TAKEN"?t("usernameTaken"):err.message==="USERNAME_INVALID"?t("usernameInvalid"):err.message==="EMAIL_NOT_VERIFIED"?(openVerification(d.email),t("verifySent")):err.message}};
$("#forgot-open").onclick=()=>{ $("#auth-dialog").close();$("#forgot-dialog").showModal()};$("#forgot-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/forgot-password",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$("#forgot-dialog").close();toast(t("resetSent"))}catch(err){toast(err.message)}};$("#reset-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/reset-password",{method:"POST",body:JSON.stringify({token:window.resetToken,password:new FormData(e.currentTarget).get("password")})});$("#reset-dialog").close();history.replaceState(null,"",location.pathname+location.hash);toast(t("resetDone"));auth("login")}catch(err){$("#reset-error").textContent=err.message}};
$("#new-topic").onclick=()=>{if(!me&&backendOnline)return auth("login");const f=$("#topic-form");try{const d=JSON.parse(localStorage.getItem(draftKey)||"{}");for(const key of ["title","body","category","tags"])if(d[key]&& !f.elements[key].value)f.elements[key].value=d[key]}catch{}$("#topic-dialog").showModal()};$("#topic-form").addEventListener("input",()=>{const f=$("#topic-form");const d=Object.fromEntries(["title","body","category","tags"].map(k=>[k,f.elements[k].value]));localStorage.setItem(draftKey,JSON.stringify(d))});$("#topic-form").onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),file=f.get("imageFile");let image="";try{if(file&&file.size)image=await fileData(file);const pollQuestion=String(f.get("pollQuestion")||"").trim(),pollOptions=String(f.get("pollOptions")||"").split("\n").map(x=>x.trim()).filter(Boolean);if((pollQuestion||pollOptions.length)&&(!pollQuestion||pollOptions.length<2))throw Error("POLL_NEEDS_OPTIONS");const d={title:f.get("title"),body:f.get("body"),category:f.get("category"),tags:f.get("tags"),image,pollQuestion,pollOptions};const result=await api("/api/topics",{method:"POST",body:JSON.stringify(d)});$("#topic-dialog").close();form.reset();localStorage.removeItem(draftKey);$("#topic-preview").hidden=true;$("#topic-body").hidden=false;location.hash=`#topic/${result.id}`}catch(err){$("#topic-error").textContent=err.message==="DUPLICATE_TOPIC"?t("duplicateTopic"):err.message==="RATE_LIMITED"?t("rateLimited"):err.message==="POLL_NEEDS_OPTIONS"||err.message==="POLL_NEEDS_QUESTION"?t("pollQuestionRequired"):err.message}};
