document.body.addEventListener("click",async e=>{const edit=e.target.closest("[data-edit-topic]");if(!edit)return;try{const d=await api(`/api/topics/${edit.dataset.editTopic}`),f=$("#edit-topic-form");f.elements.title.value=d.topic.title;f.elements.body.value=d.topic.body;f.elements.category.value=d.topic.category;f.elements.tags.value=(d.topic.tags||[]).join(", ");window.editingTopicId=d.topic.id;$("#edit-topic-error").textContent="";$("#edit-topic-dialog").showModal()}catch(err){toast(err.message)}});
