document.body.addEventListener("click",async e=>{const ec=e.target.closest("[data-edit-comment]");if(ec){const body=prompt(t("editReply"),ec.dataset.body);if(body===null)return;try{await api(`/api/comments/${ec.dataset.editComment}`,{method:"PUT",body:JSON.stringify({body})});route()}catch(err){toast(err.message)}return}const l=e.target.closest("[data-like]");if(l){if(!me&&backendOnline)return auth("login");try{await api(`/api/topics/${l.dataset.like}/like`,{method:"POST",body:"{}"});if(location.hash===`#topic/${l.dataset.like}`)openTopic(l.dataset.like);else loadTopics($("#search").value,$("#category-filter").value)}catch(err){toast(err.message)}return}const b=e.target.closest("[data-bookmark]");if(b){if(!me&&backendOnline)return auth("login");try{const d=await api(`/api/topics/${b.dataset.bookmark}/bookmark`,{method:"POST",body:"{}"});toast(t(d.saved?"saved":"unsaved"));if(location.hash==="#bookmarks")loadBookmarks()}catch(err){toast(err.message)}return}const r=e.target.closest("[data-report-type]");if(r){if(!me)return backendOnline?auth("login"):toast(lang==="ar"?"الإبلاغ يحتاج تشغيل الخادم.":"Reporting requires the server.");reportTarget={targetType:r.dataset.reportType,targetId:Number(r.dataset.reportId)};$("#report-dialog").showModal();return}const a=e.target.closest("[data-admin]");if(a){try{if(a.dataset.admin==="resolve"){await api(`/api/reports/${a.dataset.id}/resolve`,{method:"POST",body:"{}"})}else{if(!confirm(t("confirmDelete")))return;await api(a.dataset.type==="topic"?`/api/topics/${a.dataset.id}/delete`:`/api/comments/${a.dataset.id}/delete`,{method:"POST",body:"{}"})}drawAdmin();route()}catch(err){toast(err.message)}return}const ban=e.target.closest("[data-ban]");if(ban){try{await api(`/api/admin/users/${ban.dataset.ban}/ban`,{method:"POST",body:"{}"});drawAdmin()}catch(err){toast(err.message)}return}if(e.target.closest("[data-auth]"))backendOnline?auth("login"):toast(lang==="ar"?"الحسابات تحتاج تشغيل خادم Python.":"Accounts require the Python server.")});
document.body.addEventListener("click",async e=>{const m=e.target.closest("[data-message-user]");if(m){if(!me)return auth("login");messagePeer={id:Number(m.dataset.messageUser),name:m.dataset.messageName};openMessages();return}const a=e.target.closest("[data-best-answer]");if(a){try{await api(`/api/topics/${a.dataset.bestAnswer}/best-answer`,{method:"POST",body:JSON.stringify({commentId:Number(a.dataset.commentId)})});openTopic(a.dataset.bestAnswer)}catch(err){toast(err.message)}return}const u=e.target.closest("[data-follow-user]");if(u){if(!me)return auth("login");try{await api("/api/follow/user",{method:"POST",body:JSON.stringify({userId:Number(u.dataset.followUser)})});openProfile(u.dataset.followUser)}catch(err){toast(err.message)}return}const c=e.target.closest("[data-follow-category]");if(c){if(!me)return auth("login");try{await api("/api/follow/category",{method:"POST",body:JSON.stringify({category:c.dataset.followCategory})});await loadCategories()}catch(err){toast(err.message)}return}const pin=e.target.closest("[data-pin-topic]");if(pin){try{const d=await api(`/api/admin/topics/${pin.dataset.pinTopic}/pin`,{method:"POST",body:"{}"});toast(d.pinned?t("pinnedTopic"):t("unpin"));route()}catch(err){toast(err.message)}return}const vote=e.target.closest("[data-vote]");if(vote){if(!me)return auth("login");try{await api(`/api/topics/${vote.dataset.vote}/vote`,{method:"POST",body:JSON.stringify({optionIndex:Number(vote.dataset.option)})});openTopic(vote.dataset.vote)}catch(err){toast(err.message)}}});document.querySelectorAll("[data-mark]").forEach(button=>button.onclick=()=>{const area=$("#topic-body"),mark=button.dataset.mark,start=area.selectionStart,end=area.selectionEnd,value=area.value,selected=value.slice(start,end);area.setRangeText(`${mark}${selected||t("bodyLabel")}${mark}`,start,end,"select");area.focus()});$("#preview-toggle").onclick=()=>{const body=$("#topic-body"),preview=$("#topic-preview"),show=preview.hidden;if(show){preview.innerHTML=formatBody(body.value);preview.hidden=false;body.hidden=true;$("#preview-toggle").textContent=t("editText")}else{preview.hidden=true;body.hidden=false;$("#preview-toggle").textContent=t("preview")}};$("#topic-body").oninput=()=>{if(!$("#topic-preview").hidden)$("#topic-preview").innerHTML=formatBody($("#topic-body").value)};$("#category-form").onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{await api("/api/admin/categories",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await loadCategories();drawAdmin();toast(t("categoryAdded"))}catch(err){toast(err.message==="CATEGORY_EXISTS"?t("categoryExists"):err.message==="CATEGORY_INVALID"?t("categoryInvalid"):err.message)}};document.body.addEventListener("click",async e=>{const b=e.target.closest("[data-delete-category]");if(!b)return;if(!confirm(t("confirmDelete")))return;try{await api("/api/admin/categories/delete",{method:"POST",body:JSON.stringify({slug:b.dataset.deleteCategory})});await loadCategories();drawAdmin()}catch(err){toast(err.message==="CATEGORY_IN_USE"?t("categoryInUse"):err.message==="DEFAULT_CATEGORY"?t("defaultCategory"):err.message)}});$("#report-type").onchange=()=>drawAdmin();$("#report-status").onchange=()=>drawAdmin();$("#report-search").oninput=()=>drawAdmin();$("#mobile-menu").onclick=()=>{const n=$("#main-links"),open=n.classList.toggle("open");$("#mobile-menu").setAttribute("aria-expanded",String(open))};$("#main-links").addEventListener("click",()=>{$("#main-links").classList.remove("open");$("#mobile-menu").setAttribute("aria-expanded","false")});$("#load-more").onclick=()=>{topicPage++;loadTopics($("#search").value,$("#category-filter").value,$("#sort-filter").value,true)};
window.addEventListener("hashchange",route);
async function refreshBadge(){if(!me)return;try{const inbox=await api("/api/inbox"),messages=inbox.conversations.reduce((n,c)=>n+Number(c.unread||0),0),mb=$("#message-count");mb.textContent=messages;mb.hidden=!messages;const d=await api("/api/notifications?mark=0"),b=$("#notification-count");b.textContent=d.unread;b.setAttribute("aria-label",`${d.unread} ${t("notifications")}`);b.hidden=!d.unread;if(lastUnread!==null&&d.unread>lastUnread)toast(t("activityNotice"));lastUnread=d.unread}catch{}}
